(function(){
'use strict';
function fmtBytes(n){
  if(!isFinite(n)||n<0) return '-';
  var u=['B','KB','MB','GB'],i=0;
  while(n>=1024&&i<u.length-1){n/=1024;i++;}
  return (i===0?n:Math.round(n*10)/10)+' '+u[i];
}
function fmtMs(n){
  if(!isFinite(n)||n<0) return '-';
  return n<1000?(Math.round(n)+' ms'):((Math.round(n/100)/10)+' s');
}
function hostOf(u){
  var m=/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\/([^\/?#]+)/.exec(String(u||''));
  return m?m[1]:'(相对路径)';
}
function typeOf(mime,url){
  var m=String(mime||'').split(';')[0].toLowerCase();
  if(m.indexOf('javascript')>=0||m.indexOf('ecmascript')>=0) return 'JS';
  if(m==='text/css') return 'CSS';
  if(m.indexOf('html')>=0) return 'HTML';
  if(m.indexOf('json')>=0) return 'JSON';
  if(m.indexOf('xml')>=0) return 'XML';
  if(m.indexOf('image/')===0) return '图片';
  if(m.indexOf('font')>=0||/\.(woff2?|ttf|otf|eot)(\?|$)/i.test(url||'')) return '字体';
  if(m.indexOf('video/')===0||m.indexOf('audio/')===0) return '音视频';
  if(m) return '其他';
  return '未知';
}
function num(v){ var n=Number(v); return isFinite(n)&&n>0?n:0; }
function analyze(text){
  if(typeof text!=='string'||!text.trim()) return {value:null,error:'请粘贴 HAR 文件内容（DevTools 网络面板可导出）'};
  var har;
  try{ har=JSON.parse(text); }catch(e){ return {value:null,error:'JSON 解析失败：'+e.message}; }
  var log=har&&har.log?har.log:har;
  if(!log||!log.entries||!log.entries.length) return {value:null,error:'未找到 log.entries，确认这是 HAR 文件'};
  var es=log.entries,list=[],i;
  var totalTime=0,totalTransfer=0,totalContent=0,cached=0;
  var tSum={blocked:0,dns:0,connect:0,ssl:0,send:0,wait:0,receive:0};
  var byType={},byDomain={},statuses={},methods={};
  var tMin=null,tMax=null;
  for(i=0;i<es.length;i++){
    var e=es[i]||{},req=e.request||{},res=e.response||{},c=res.content||{},tm=e.timings||{};
    var url=req.url||'',host=hostOf(url);
    var content=num(c.size);
    var transfer=num(e._transferSize);
    if(!transfer) transfer=num(res.bodySize)+num(res.headersSize);
    if(!transfer) transfer=content;
    var dur=num(e.time);
    var st=num(res.status);
    var isCache=(st===304)||(res._fromCache?true:false)||(num(res.bodySize)===0&&content>0&&st===200&&num(e._transferSize)===0);
    var ty=typeOf(c.mimeType||res.content&&res.content.mimeType,url);
    totalTime+=dur; totalTransfer+=transfer; totalContent+=content;
    if(isCache) cached++;
    var kk;
    for(kk in tSum){ var v=Number(tm[kk]); if(isFinite(v)&&v>0) tSum[kk]+=v; }
    if(!byType[ty]) byType[ty]={type:ty,count:0,bytes:0,time:0};
    byType[ty].count++; byType[ty].bytes+=transfer; byType[ty].time+=dur;
    if(!byDomain[host]) byDomain[host]={domain:host,count:0,bytes:0,time:0};
    byDomain[host].count++; byDomain[host].bytes+=transfer; byDomain[host].time+=dur;
    var sk=st?String(st):'0';
    statuses[sk]=(statuses[sk]||0)+1;
    var mk=(req.method||'GET').toUpperCase();
    methods[mk]=(methods[mk]||0)+1;
    var started=e.startedDateTime?Date.parse(e.startedDateTime):NaN;
    if(isFinite(started)){
      if(tMin===null||started<tMin) tMin=started;
      var end=started+dur;
      if(tMax===null||end>tMax) tMax=end;
    }
    list.push({url:url,short:url.split('?')[0].split('/').pop()||host,host:host,method:mk,status:st,
               type:ty,transfer:transfer,content:content,time:dur,cached:isCache,
               wait:num(tm.wait),blocked:num(tm.blocked),receive:num(tm.receive),start:started});
  }
  function arr(o){ var a=[],k; for(k in o) a.push(o[k]); return a; }
  var types=arr(byType).sort(function(a,b){return b.bytes-a.bytes;});
  var domains=arr(byDomain).sort(function(a,b){return b.bytes-a.bytes;});
  var slowest=list.slice().sort(function(a,b){return b.time-a.time;}).slice(0,10);
  var largest=list.slice().sort(function(a,b){return b.transfer-a.transfer;}).slice(0,10);
  var errors=list.filter(function(x){return x.status>=400||x.status===0;});
  var span=(tMin!==null&&tMax!==null)?(tMax-tMin):totalTime;
  var advice=[];
  var jsBytes=byType['JS']?byType['JS'].bytes:0, imgBytes=byType['图片']?byType['图片'].bytes:0;
  if(jsBytes>1024*1024) advice.push('JS 传输量 '+fmtBytes(jsBytes)+' 偏大，考虑代码分割与按需加载');
  if(imgBytes>2*1024*1024) advice.push('图片传输量 '+fmtBytes(imgBytes)+' 偏大，考虑 WebP/AVIF 与响应式尺寸');
  if(domains.length>10) advice.push('涉及 '+domains.length+' 个域名，跨域连接握手成本高，可合并或预连接');
  if(errors.length) advice.push('存在 '+errors.length+' 个失败请求（4xx/5xx/0），优先排查');
  if(list.length>80) advice.push('请求数 '+list.length+' 偏多，可合并静态资源或启用 HTTP/2 多路复用');
  if(cached===0&&list.length>10) advice.push('没有命中缓存的请求，检查 Cache-Control 与 ETag 配置');
  if(tSum.wait>totalTime*0.5&&totalTime>0) advice.push('等待服务器响应（TTFB）占总耗时超过一半，瓶颈在后端');
  if(!advice.length) advice.push('未发现明显性能问题');
  return {value:{
    summary:{count:list.length,span:span,totalTime:totalTime,totalTransfer:totalTransfer,totalContent:totalContent,
             cached:cached,errors:errors.length,domains:domains.length,
             avgTime:list.length?totalTime/list.length:0,
             saved:totalContent>totalTransfer?(totalContent-totalTransfer):0},
    types:types,domains:domains.slice(0,10),statuses:statuses,methods:methods,
    slowest:slowest,largest:largest,errorList:errors.slice(0,10),timings:tSum,advice:advice,
    creator:(log.creator&&log.creator.name)||'未知',pages:(log.pages&&log.pages.length)||0
  },error:null};
}
var API={analyze:analyze,fmtBytes:fmtBytes,fmtMs:fmtMs,hostOf:hostOf,typeOf:typeOf};
if(typeof module!=='undefined'&&module.exports) module.exports=API;
if(typeof window!=='undefined') window.__HarForge__=API;
})();
